// ===== src/integrate.cpp =====
// poncelet — integrator core. FP-CONTRACT-OFF TRANSLATION UNIT.
// SPDX-License-Identifier: MIT
//
// Build rules for this file (enforced in CMakeLists.txt):
//   * no fast-math / -ffast-math anywhere
//   * -ffp-contract=off  (GCC/Clang)  |  /fp:precise  (MSVC)
//
// Every arithmetic step runs on a template parameter `Acc_integrate` via the `Core_integrate<Acc_integrate>`
// struct below. `Core_integrate<Real>` is the float/double core — byte-for-bit the pre-B6
// path (acc_* forward straight to <cmath>, AVec3<Real> matches the old Vec3
// component order). `Core_integrate<Fx32>` is the Q32.32 fixed-point BitExact core: the
// deterministic sqrt (B3), transcendental LUTs (B4) and drag-LUT sampling (B5),
// integer-only and identical across platforms. Each public entry point takes a
// `bool bitExact` and dispatches; config::Determinism::BitExact sets it.



namespace pon::detail {

namespace {

// Drag / lift LUT sampling on the accumulator: the double path keeps
// Lut1D::sample(); the fixed-point path uses the bit-identical port (B5).
inline Real acc_lut_sample(const Lut1D& l, Real x) { return l.sample(x); }
inline Fx32 acc_lut_sample(const Lut1D& l, Fx32 x) { return lut_sample_fx(l, x); }

template <class Acc_integrate>
struct Core_integrate {
    using AVec = AVec3<Acc_integrate>;

    static AVec A(Vec3 v) { return {Acc_integrate(v.x), Acc_integrate(v.y), Acc_integrate(v.z)}; }
    static Vec3 V(AVec a) { return {to_real(a.x), to_real(a.y), to_real(a.z)}; }
    static Acc_integrate  mn(Acc_integrate a, Acc_integrate b) { return a < b ? a : b; }

    // --- total specific force on a point mass -----------------------------
    static AVec flight_accel_a(const FlightModel& m, AVec pos, AVec vel, Acc_integrate tRel) {
        AVec a = A(m.gravity);

        // Guidance / thrust / caller course-correction (Phase 19 item 5).
        if (m.externalAccel.x != 0.0 || m.externalAccel.y != 0.0 ||
            m.externalAccel.z != 0.0)
            a += A(m.externalAccel);

        // Coriolis:  a += -2 Ω × v. Gyroscopic spin drift — Litz closed form
        // D(t) = C·t^1.83 applied as D''(t) = C·1.83·0.83·t^-0.17 along the
        // signed drift direction (guarded below 1 ms). Both default-off.
        if (m.coriolisOmega.x != 0.0 || m.coriolisOmega.y != 0.0 ||
            m.coriolisOmega.z != 0.0)
            a -= cross(A(m.coriolisOmega), vel) * Acc_integrate(2);
        if (m.spinDriftCoeff > 0.0) {
            const Acc_integrate t = Acc_integrate(m.flightTime0) + tRel;
            if (t > Acc_integrate(1.0e-3)) {
                const Acc_integrate acc = Acc_integrate(m.spinDriftCoeff) * Acc_integrate(1.83) * Acc_integrate(0.83) *
                                acc_pow_neg017(t);
                a += A(m.spinDriftDir) * acc;
            }
        }

        if (m.rhoEff <= 0.0) return a;

        AVec vRel = vel;
        if (m.env)
            vRel -= A(m.env->windAt(V(pos), to_real(Acc_integrate(m.windTime) + tRel)));
        const Acc_integrate speed = acc_sqrt(dot(vRel, vRel));
        if (speed <= Acc_integrate(0)) return a;

        // Drag:  dragRet(x) = i·Cd(x)·A / 2m;  |a_drag| = dragRet·rho·v².
        // x = speed·dragAbscissaScale is Mach (1/a) or Reynolds (d/ν). Under
        // LocalSpeedSound the Mach abscissa is scaled by sqrt(siteT / T(alt)).
        if (m.dragRet) {
            Acc_integrate scale = Acc_integrate(m.dragAbscissaScale);
            if (m.soundLapse_KpM != 0.0) {
                const Acc_integrate Talt = Acc_integrate(m.siteTemp_K) + Acc_integrate(m.soundLapse_KpM) * pos.y;
                if (Talt > Acc_integrate(0))
                    scale *= acc_sqrt(Acc_integrate(m.siteTemp_K) / Talt);
            }
            const Acc_integrate x    = speed * scale;
            const Acc_integrate kret = acc_lut_sample(*m.dragRet, x) * Acc_integrate(m.dragScaleExtra);
            const Acc_integrate s    = kret * Acc_integrate(m.rhoEff) * speed; // 1/s, along -vRel
            a -= vRel * s;
        }

        // Magnus / lift:  a_lift = Cl(S)·(0.5 A/m)·rho·|v_rel|·(ŝ × v_rel).
        // S = |ω| r / |v_rel|. Skipped for rifle spin (spinAxis left zeroed).
        if (m.liftVsSpin && m.spin_radps != 0.0 &&
            (m.spinAxis.x != 0.0 || m.spinAxis.y != 0.0 || m.spinAxis.z != 0.0)) {
            const Acc_integrate S  = Acc_integrate(std::fabs(m.spin_radps) * m.spinRadius_m) / speed;
            const Acc_integrate cl = acc_lut_sample(*m.liftVsSpin, S);
            if (cl != Acc_integrate(0)) {
                const AVec dir = cross(A(m.spinAxis), vRel); // |·| = |v_rel| sinθ
                const Acc_integrate  k   = cl * Acc_integrate(m.liftAreaOver2m) * Acc_integrate(m.rhoEff) * speed;
                a += dir * k;
            }
        }
        return a;
    }

    static Real linear_drag_rate(const FlightModel& m, Real speedR) {
        if (!m.dragRet || m.rhoEff <= Real(0) || speedR <= Real(0)) return Real(0);
        const Acc_integrate speed = Acc_integrate(speedR);
        const Acc_integrate x     = speed * Acc_integrate(m.dragAbscissaScale);
        return to_real(acc_lut_sample(*m.dragRet, x) * Acc_integrate(m.dragScaleExtra) *
                       Acc_integrate(m.rhoEff) * speed);
    }

    // --- point-mass integrators -----------------------------------------
    static void step_semi_implicit(const FlightModel& m, Vec3& pos, Vec3& vel,
                                   Seconds tRel, Seconds h) {
        AVec      p = A(pos), v = A(vel);
        const Acc_integrate H = Acc_integrate(h);
        const AVec a = flight_accel_a(m, p, v, Acc_integrate(tRel));
        v += a * H;
        p += v * H;
        pos = V(p);
        vel = V(v);
    }

    static void step_rk4(const FlightModel& m, Vec3& pos, Vec3& vel,
                         Seconds tRel, Seconds h) {
        const AVec pos0 = A(pos), vel0 = A(vel);
        const Acc_integrate  H  = Acc_integrate(h);
        const Acc_integrate  t0 = Acc_integrate(tRel);
        const Acc_integrate  h2 = H * Acc_integrate(0.5);

        const AVec k1x = vel0;
        const AVec k1v = flight_accel_a(m, pos0, vel0, t0);

        const AVec p2 = pos0 + k1x * h2;
        const AVec v2 = vel0 + k1v * h2;
        const AVec k2x = v2;
        const AVec k2v = flight_accel_a(m, p2, v2, t0 + h2);

        const AVec p3 = pos0 + k2x * h2;
        const AVec v3 = vel0 + k2v * h2;
        const AVec k3x = v3;
        const AVec k3v = flight_accel_a(m, p3, v3, t0 + h2);

        const AVec p4 = pos0 + k3x * H;
        const AVec v4 = vel0 + k3v * H;
        const AVec k4x = v4;
        const AVec k4v = flight_accel_a(m, p4, v4, t0 + H);

        const Acc_integrate sixth = H / Acc_integrate(6);
        pos = V(pos0 + (k1x + (k2x + k3x) * Acc_integrate(2) + k4x) * sixth);
        vel = V(vel0 + (k1v + (k2v + k3v) * Acc_integrate(2) + k4v) * sixth);
    }

    static void step_rkck(const FlightModel& m, Vec3 pos, Vec3 vel, Seconds tRel,
                          Seconds h, Vec3& pos5, Vec3& vel5, Real& posErr_m,
                          Real& velErr_mps) {
        // Cash-Karp RK4(5). `const` not `constexpr` — Fx32 divide is a runtime
        // op; for Acc_integrate = Real the compiler still folds these to the same values.
        const Acc_integrate a2 = Acc_integrate(1) / Acc_integrate(5);
        const Acc_integrate a3 = Acc_integrate(3) / Acc_integrate(10);
        const Acc_integrate a4 = Acc_integrate(3) / Acc_integrate(5);
        const Acc_integrate a5 = Acc_integrate(1);
        const Acc_integrate a6 = Acc_integrate(7) / Acc_integrate(8);

        const Acc_integrate b21 = Acc_integrate(1) / Acc_integrate(5);
        const Acc_integrate b31 = Acc_integrate(3) / Acc_integrate(40),      b32 = Acc_integrate(9) / Acc_integrate(40);
        const Acc_integrate b41 = Acc_integrate(3) / Acc_integrate(10),      b42 = Acc_integrate(-9) / Acc_integrate(10),
                  b43 = Acc_integrate(6) / Acc_integrate(5);
        const Acc_integrate b51 = Acc_integrate(-11) / Acc_integrate(54),    b52 = Acc_integrate(5) / Acc_integrate(2),
                  b53 = Acc_integrate(-70) / Acc_integrate(27),    b54 = Acc_integrate(35) / Acc_integrate(27);
        const Acc_integrate b61 = Acc_integrate(1631) / Acc_integrate(55296), b62 = Acc_integrate(175) / Acc_integrate(512),
                  b63 = Acc_integrate(575) / Acc_integrate(13824),  b64 = Acc_integrate(44275) / Acc_integrate(110592),
                  b65 = Acc_integrate(253) / Acc_integrate(4096);

        const Acc_integrate c1 = Acc_integrate(37) / Acc_integrate(378),   c3 = Acc_integrate(250) / Acc_integrate(621),
                  c4 = Acc_integrate(125) / Acc_integrate(594),  c6 = Acc_integrate(512) / Acc_integrate(1771);
        const Acc_integrate d1 = Acc_integrate(2825) / Acc_integrate(27648), d3 = Acc_integrate(18575) / Acc_integrate(48384),
                  d4 = Acc_integrate(13525) / Acc_integrate(55296), d5 = Acc_integrate(277) / Acc_integrate(14336),
                  d6 = Acc_integrate(1) / Acc_integrate(4);

        const AVec pos0 = A(pos), vel0 = A(vel);
        const Acc_integrate  H  = Acc_integrate(h);
        const Acc_integrate  t0 = Acc_integrate(tRel);

        const AVec k1x = vel0;
        const AVec k1v = flight_accel_a(m, pos0, vel0, t0);

        const AVec k2x = vel0 + k1v * (H * b21);
        const AVec k2v = flight_accel_a(m, pos0 + k1x * (H * b21),
                                        vel0 + k1v * (H * b21), t0 + H * a2);

        const AVec k3x = vel0 + (k1v * b31 + k2v * b32) * H;
        const AVec k3v = flight_accel_a(m, pos0 + (k1x * b31 + k2x * b32) * H,
                                        vel0 + (k1v * b31 + k2v * b32) * H, t0 + H * a3);

        const AVec k4x = vel0 + (k1v * b41 + k2v * b42 + k3v * b43) * H;
        const AVec k4v = flight_accel_a(m, pos0 + (k1x * b41 + k2x * b42 + k3x * b43) * H,
                                        vel0 + (k1v * b41 + k2v * b42 + k3v * b43) * H,
                                        t0 + H * a4);

        const AVec k5x = vel0 + (k1v * b51 + k2v * b52 + k3v * b53 + k4v * b54) * H;
        const AVec k5v = flight_accel_a(
            m, pos0 + (k1x * b51 + k2x * b52 + k3x * b53 + k4x * b54) * H,
            vel0 + (k1v * b51 + k2v * b52 + k3v * b53 + k4v * b54) * H, t0 + H * a5);

        const AVec k6x = vel0 + (k1v * b61 + k2v * b62 + k3v * b63 + k4v * b64 + k5v * b65) * H;
        const AVec k6v = flight_accel_a(
            m, pos0 + (k1x * b61 + k2x * b62 + k3x * b63 + k4x * b64 + k5x * b65) * H,
            vel0 + (k1v * b61 + k2v * b62 + k3v * b63 + k4v * b64 + k5v * b65) * H,
            t0 + H * a6);

        const AVec p5 = pos0 + (k1x * c1 + k3x * c3 + k4x * c4 + k6x * c6) * H;
        const AVec v5 = vel0 + (k1v * c1 + k3v * c3 + k4v * c4 + k6v * c6) * H;
        pos5 = V(p5);
        vel5 = V(v5);

        const AVec pos4 = pos0 + (k1x * d1 + k3x * d3 + k4x * d4 + k5x * d5 + k6x * d6) * H;
        const AVec vel4 = vel0 + (k1v * d1 + k3v * d3 + k4v * d4 + k5v * d5 + k6v * d6) * H;

        posErr_m   = to_real(acc_sqrt(dot(p5 - pos4, p5 - pos4)));
        velErr_mps = to_real(acc_sqrt(dot(v5 - vel4, v5 - vel4)));
    }

    // --- 6-DOF rigid-body flight (PrecisionFlag::SixDOF) ---------------
    struct ARigidState {
        AVec pos, vel, nose, omegaT;
        Acc_integrate  spin{}, roll{};
    };
    struct RigidDeriv {
        AVec dpos, dvel, dnose, domegaT;
        Acc_integrate  dspin{}, droll{};
    };

    static RigidDeriv rigid_deriv(const RigidModel& m, const ARigidState& s,
                                  Acc_integrate tRel, Real* alphaOut) {
        RigidDeriv d;
        d.dpos    = s.vel;
        d.dnose   = cross(s.omegaT, s.nose);
        d.domegaT = AVec{Acc_integrate(0), Acc_integrate(0), Acc_integrate(0)};
        d.dspin   = Acc_integrate(0);
        d.droll   = s.spin;

        AVec a = flight_accel_a(m.flight, s.pos, s.vel, tRel);

        AVec vRel = s.vel;
        if (m.flight.env)
            vRel -= A(m.flight.env->windAt(V(s.pos),
                                           to_real(Acc_integrate(m.flight.windTime) + tRel)));
        const Acc_integrate speed = acc_sqrt(dot(vRel, vRel));

        Acc_integrate alpha = Acc_integrate(0);
        if (speed > Acc_integrate(1e-6) && m.rhoEff > Real(0)) {
            const AVec vhat = vRel * (Acc_integrate(1) / speed);
            Acc_integrate c = dot(s.nose, vhat);
            c = c > Acc_integrate(1) ? Acc_integrate(1) : (c < Acc_integrate(-1) ? Acc_integrate(-1) : c);
            alpha = acc_acos(c);
            const Acc_integrate sinA = acc_sin(alpha);

            const Acc_integrate qd_over_m =
                Acc_integrate(0.5) * Acc_integrate(m.rhoEff) * speed * speed * Acc_integrate(m.refArea_m2) / Acc_integrate(m.mass_kg);

            AVec yawDir = s.nose - vhat * c;
            const Acc_integrate yl = acc_sqrt(dot(yawDir, yawDir));
            if (yl > Acc_integrate(1e-9)) {
                yawDir = yawDir * (Acc_integrate(1) / yl);
                a += yawDir * (qd_over_m * Acc_integrate(m.CLa) * sinA);
            }
            a -= vhat * (qd_over_m * Acc_integrate(m.CDa2) * alpha * alpha);

            const Acc_integrate qdSd =
                Acc_integrate(0.5) * Acc_integrate(m.rhoEff) * speed * speed * Acc_integrate(m.refArea_m2) * Acc_integrate(m.refLen_m);
            Acc_integrate CMa = Acc_integrate(m.CMa);
            if (m.invSpeedOfSound > Real(0)) {
                const Acc_integrate mach = speed * Acc_integrate(m.invSpeedOfSound);
                if (mach >= Acc_integrate(0.9) && mach <= Acc_integrate(1.2)) CMa *= Acc_integrate(m.transonicMul);
            }

            AVec tau{Acc_integrate(0), Acc_integrate(0), Acc_integrate(0)};
            const AVec nxv = cross(s.nose, vhat);
            const Acc_integrate  nxvl = acc_sqrt(dot(nxv, nxv));
            if (nxvl > Acc_integrate(1e-9)) {
                const AVec sHat = nxv * (Acc_integrate(1) / nxvl);
                tau -= sHat * (qdSd * CMa * sinA);
                const AVec planeDir = cross(s.nose, sHat);
                const Acc_integrate  spinTerm = s.spin * Acc_integrate(m.refLen_m) / (Acc_integrate(2) * speed);
                tau += planeDir * (qdSd * Acc_integrate(m.CMpa) * spinTerm * sinA);
            }
            tau += s.omegaT * (qdSd * Acc_integrate(m.CMq) * Acc_integrate(m.refLen_m) / (Acc_integrate(2) * speed));
            d.dspin = qdSd * Acc_integrate(m.Clp) * (s.spin * Acc_integrate(m.refLen_m) / (Acc_integrate(2) * speed)) / Acc_integrate(m.Ix);

            const AVec tauPerp = tau - s.nose * dot(tau, s.nose);
            const AVec gyro    = cross(s.nose, s.omegaT) * (Acc_integrate(m.Ix) * s.spin);
            d.domegaT = (tauPerp - gyro) * (Acc_integrate(1) / Acc_integrate(m.It));
        }

        d.dvel = a;
        if (alphaOut) *alphaOut = to_real(alpha);
        return d;
    }

    static ARigidState rigid_advance(const ARigidState& a, const RigidDeriv& k, Acc_integrate f) {
        ARigidState r;
        r.pos    = a.pos    + k.dpos    * f;
        r.vel    = a.vel    + k.dvel    * f;
        r.nose   = a.nose   + k.dnose   * f;
        r.omegaT = a.omegaT + k.domegaT * f;
        r.spin   = a.spin   + k.dspin   * f;
        r.roll   = a.roll   + k.droll   * f;
        return r;
    }

    static void step_rigid_rk4(const RigidModel& m, RigidState& s, Seconds tRel,
                               Seconds h, Real& alpha_out) {
        const Acc_integrate H  = Acc_integrate(h);
        const Acc_integrate t0 = Acc_integrate(tRel);
        const Acc_integrate h2 = H * Acc_integrate(0.5);

        ARigidState s0;
        s0.pos = A(s.pos); s0.vel = A(s.vel); s0.nose = A(s.nose);
        s0.omegaT = A(s.omegaT); s0.spin = Acc_integrate(s.spin); s0.roll = Acc_integrate(s.roll);

        const RigidDeriv k1 = rigid_deriv(m, s0, t0, &alpha_out);
        const RigidDeriv k2 = rigid_deriv(m, rigid_advance(s0, k1, h2), t0 + h2, nullptr);
        const RigidDeriv k3 = rigid_deriv(m, rigid_advance(s0, k2, h2), t0 + h2, nullptr);
        const RigidDeriv k4 = rigid_deriv(m, rigid_advance(s0, k3, H),  t0 + H,  nullptr);

        const Acc_integrate sixth = H / Acc_integrate(6);
        AVec pos    = s0.pos    + (k1.dpos    + (k2.dpos    + k3.dpos)    * Acc_integrate(2) + k4.dpos)    * sixth;
        AVec vel    = s0.vel    + (k1.dvel    + (k2.dvel    + k3.dvel)    * Acc_integrate(2) + k4.dvel)    * sixth;
        AVec nose   = s0.nose   + (k1.dnose   + (k2.dnose   + k3.dnose)   * Acc_integrate(2) + k4.dnose)   * sixth;
        AVec omegaT = s0.omegaT + (k1.domegaT + (k2.domegaT + k3.domegaT) * Acc_integrate(2) + k4.domegaT) * sixth;
        Acc_integrate  spin   = s0.spin   + (k1.dspin   + (k2.dspin   + k3.dspin)   * Acc_integrate(2) + k4.dspin)   * sixth;
        Acc_integrate  roll   = s0.roll   + (k1.droll   + (k2.droll   + k3.droll)   * Acc_integrate(2) + k4.droll)   * sixth;

        const Acc_integrate nl = acc_sqrt(dot(nose, nose));
        if (nl > Acc_integrate(0)) nose = nose * (Acc_integrate(1) / nl);
        omegaT = omegaT - nose * dot(omegaT, nose);

        s.pos = V(pos); s.vel = V(vel); s.nose = V(nose); s.omegaT = V(omegaT);
        s.spin = to_real(spin); s.roll = to_real(roll);
    }

    static int adaptive_substeps(Vec3 vel, Vec3 accel, Seconds dt, Real posTol_m,
                                 Real maxDist_m, int maxSub) {
        if (dt <= Seconds(0) || maxSub < 1) return 1;

        const Acc_integrate speed = acc_sqrt(dot(A(vel), A(vel)));
        const Acc_integrate acc   = acc_sqrt(dot(A(accel), A(accel)));

        Acc_integrate h = Acc_integrate(dt);
        if (acc > Acc_integrate(0) && posTol_m > Real(0))
            h = mn(h, acc_sqrt(Acc_integrate(2) * Acc_integrate(posTol_m) / acc));
        if (speed > Acc_integrate(0) && maxDist_m > Real(0))
            h = mn(h, Acc_integrate(maxDist_m) / speed);

        if (h <= Acc_integrate(0)) return maxSub;
        int n = static_cast<int>(std::ceil(to_real(Acc_integrate(dt) / h)));
        if (n < 1) n = 1;
        if (n > maxSub) n = maxSub;
        return n;
    }

    static void analytic_at(const AnalyticTrajectory& tr, Seconds t, Vec3& pos, Vec3& vel) {
        const AVec x0a = A(tr.x0), v0a = A(tr.v0), ga = A(tr.gravity);
        const Acc_integrate  ta = Acc_integrate(t);
        const Acc_integrate  ca = Acc_integrate(tr.c);
        if (ca <= Acc_integrate(0)) {
            vel = V(v0a + ga * ta);
            pos = V(x0a + v0a * ta + ga * (Acc_integrate(0.5) * ta * ta));
            return;
        }
        const AVec vTerm = ga * (Acc_integrate(1) / ca);
        const Acc_integrate  e     = acc_exp(-ca * ta);
        const AVec dv0   = v0a - vTerm;
        vel = V(vTerm + dv0 * e);
        pos = V(x0a + vTerm * ta + dv0 * ((Acc_integrate(1) - e) / ca));
    }
};

} // namespace

// --- public entry points: dispatch on `bitExact` --------------------------

Vec3 flight_accel(const FlightModel& m, Vec3 pos, Vec3 vel, Seconds tRel, bool bx) {
    return bx ? Core_integrate<Fx32>::V(Core_integrate<Fx32>::flight_accel_a(
                    m, Core_integrate<Fx32>::A(pos), Core_integrate<Fx32>::A(vel), Fx32(tRel)))
              : Core_integrate<Real>::V(Core_integrate<Real>::flight_accel_a(
                    m, Core_integrate<Real>::A(pos), Core_integrate<Real>::A(vel), Real(tRel)));
}

Real linear_drag_rate(const FlightModel& m, Real speed, bool bx) {
    return bx ? Core_integrate<Fx32>::linear_drag_rate(m, speed)
              : Core_integrate<Real>::linear_drag_rate(m, speed);
}

void step_semi_implicit(const FlightModel& m, Vec3& pos, Vec3& vel, Seconds tRel,
                        Seconds h, bool bx) {
    if (bx) Core_integrate<Fx32>::step_semi_implicit(m, pos, vel, tRel, h);
    else    Core_integrate<Real>::step_semi_implicit(m, pos, vel, tRel, h);
}

void step_rk4(const FlightModel& m, Vec3& pos, Vec3& vel, Seconds tRel, Seconds h,
              bool bx) {
    if (bx) Core_integrate<Fx32>::step_rk4(m, pos, vel, tRel, h);
    else    Core_integrate<Real>::step_rk4(m, pos, vel, tRel, h);
}

void step_rkck(const FlightModel& m, Vec3 pos, Vec3 vel, Seconds tRel, Seconds h,
               Vec3& pos5, Vec3& vel5, Real& posErr_m, Real& velErr_mps, bool bx) {
    if (bx) Core_integrate<Fx32>::step_rkck(m, pos, vel, tRel, h, pos5, vel5, posErr_m, velErr_mps);
    else    Core_integrate<Real>::step_rkck(m, pos, vel, tRel, h, pos5, vel5, posErr_m, velErr_mps);
}

// AdaptiveRKF45's step-size controller (sim.cpp's advanceIntegratedAdaptive)
// used a bare std::pow(ratio, 0.2) regardless of bitExact_ — the one libm
// call left in that path, flagged as a known gap since Part B shipped.
// Dispatches the same way every other Acc_integrate-templated entry point here does;
// the Fx32 side is a LUT (fixed_lut.hpp's fx_pow_ratio02), not a real
// std::pow, so it's bit-identical on every platform.
Real pow_ratio02(Real ratio, bool bx) {
    return bx ? to_real(acc_pow_ratio02(Fx32(ratio))) : acc_pow_ratio02(ratio);
}

void step_rigid_rk4(const RigidModel& m, RigidState& s, Seconds tRel, Seconds h,
                    Real& alpha_out, bool bx) {
    if (bx) Core_integrate<Fx32>::step_rigid_rk4(m, s, tRel, h, alpha_out);
    else    Core_integrate<Real>::step_rigid_rk4(m, s, tRel, h, alpha_out);
}

int adaptive_substeps(Vec3 vel, Vec3 accel, Seconds dt, Real posTol_m,
                      Real maxDist_m, int maxSub, bool bx) {
    return bx ? Core_integrate<Fx32>::adaptive_substeps(vel, accel, dt, posTol_m, maxDist_m, maxSub)
              : Core_integrate<Real>::adaptive_substeps(vel, accel, dt, posTol_m, maxDist_m, maxSub);
}

void AnalyticTrajectory::at(Seconds t, Vec3& pos, Vec3& vel) const {
    if (bitExact) Core_integrate<Fx32>::analytic_at(*this, t, pos, vel);
    else          Core_integrate<Real>::analytic_at(*this, t, pos, vel);
}

} // namespace pon::detail

